=== FILE: apb_regs.v ===
`timescale 1ns / 1ps
`default_nettype none

// apb_regs: four 32-bit read/write registers behind an APB4 completer port.
// Implements microarchitecture.md: zero wait states, no state machine,
// access = psel && penable, PSLVERR policy for unmapped addresses.

module apb_regs #(
    parameter ADDR_WIDTH = 8,
    parameter DATA_WIDTH = 32
) (
    input  wire                    pclk,
    input  wire                    presetn,
    input  wire [ADDR_WIDTH-1:0]   paddr,
    input  wire                    psel,
    input  wire                    penable,
    input  wire                    pwrite,
    input  wire [DATA_WIDTH-1:0]   pwdata,
    input  wire [DATA_WIDTH/8-1:0] pstrb,
    output wire [DATA_WIDTH-1:0]   prdata,
    output wire                    pready,
    output wire                    pslverr
);

    localparam STRB_WIDTH = DATA_WIDTH / 8;

    // Register file: four separate flop registers.
    reg  [DATA_WIDTH-1:0] reg0;
    reg  [DATA_WIDTH-1:0] reg1;
    reg  [DATA_WIDTH-1:0] reg2;
    reg  [DATA_WIDTH-1:0] reg3;

    // Access phase and address decode.
    wire       access        = psel && penable;
    wire       addr_aligned  = (paddr[1:0] == 2'b00);
    wire       addr_in_range = (paddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});
    wire       mapped        = addr_aligned && addr_in_range;
    wire [1:0] reg_idx       = paddr[3:2];
    wire       wr_access     = access && pwrite && mapped;
    wire       rd_access     = access && !pwrite && mapped;

    wire we0 = wr_access && (reg_idx == 2'd0);
    wire we1 = wr_access && (reg_idx == 2'd1);
    wire we2 = wr_access && (reg_idx == 2'd2);
    wire we3 = wr_access && (reg_idx == 2'd3);

    // Next-state values: byte merge of pwdata under pstrb.
    wire [DATA_WIDTH-1:0] reg0_d;
    wire [DATA_WIDTH-1:0] reg1_d;
    wire [DATA_WIDTH-1:0] reg2_d;
    wire [DATA_WIDTH-1:0] reg3_d;

    genvar gb;
    generate
        for (gb = 0; gb < STRB_WIDTH; gb = gb + 1) begin : g_byte
            assign reg0_d[8*gb +: 8] = (we0 && pstrb[gb]) ? pwdata[8*gb +: 8] : reg0[8*gb +: 8];
            assign reg1_d[8*gb +: 8] = (we1 && pstrb[gb]) ? pwdata[8*gb +: 8] : reg1[8*gb +: 8];
            assign reg2_d[8*gb +: 8] = (we2 && pstrb[gb]) ? pwdata[8*gb +: 8] : reg2[8*gb +: 8];
            assign reg3_d[8*gb +: 8] = (we3 && pstrb[gb]) ? pwdata[8*gb +: 8] : reg3[8*gb +: 8];
        end
    endgenerate

    // Register block: synchronous active-low reset, then q <= d.
    always @(posedge pclk) begin
        if (!presetn) begin
            reg0 <= {DATA_WIDTH{1'b0}};
            reg1 <= {DATA_WIDTH{1'b0}};
            reg2 <= {DATA_WIDTH{1'b0}};
            reg3 <= {DATA_WIDTH{1'b0}};
        end else begin
            reg0 <= reg0_d;
            reg1 <= reg1_d;
            reg2 <= reg2_d;
            reg3 <= reg3_d;
        end
    end

    // Read multiplexer.
    reg [DATA_WIDTH-1:0] rd_mux;
    always @* begin
        case (reg_idx)
            2'd0:    rd_mux = reg0;
            2'd1:    rd_mux = reg1;
            2'd2:    rd_mux = reg2;
            default: rd_mux = reg3;
        endcase
    end

    assign prdata  = rd_access ? rd_mux : {DATA_WIDTH{1'b0}};
    assign pready  = 1'b1;
    assign pslverr = access && !mapped;

`ifdef FORMAL
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge pclk) f_past_valid <= 1'b1;

    // Independent decode, read model and register view.
    wire f_access = psel && penable;
    wire f_mapped = (paddr == 0) || (paddr == 4) || (paddr == 8) || (paddr == 12);
    wire [4*DATA_WIDTH-1:0] f_regs = {reg3, reg2, reg1, reg0};

    reg [DATA_WIDTH-1:0] f_rd;
    always @(*) begin
        f_rd = {DATA_WIDTH{1'b0}};
        if (paddr == 0)  f_rd = reg0;
        if (paddr == 4)  f_rd = reg1;
        if (paddr == 8)  f_rd = reg2;
        if (paddr == 12) f_rd = reg3;
    end

    // Manager assumptions (this completer's own psel only).
    always @(*) begin
        if (!f_past_valid) assume(!presetn);
        if (!presetn)      assume(!psel);
    end

    always @(posedge pclk) begin
        if (f_past_valid) begin
            if ($past(psel && !penable)) begin
                assume(psel && penable);
                assume(paddr  == $past(paddr));
                assume(pwrite == $past(pwrite));
                assume(pwdata == $past(pwdata));
                assume(pstrb  == $past(pstrb));
            end
            if ($past(psel && penable)) assume(!(psel && penable));
            if (psel && penable)        assume($past(psel && !penable));
        end
    end

    // Response properties.
    always @(*) begin
        assert(pready);
        if (!f_access) begin
            assert(prdata == {DATA_WIDTH{1'b0}});
            assert(!pslverr);
        end else begin
            assert(pslverr == !f_mapped);
            if (!pwrite && f_mapped)
                assert(prdata == f_rd);
            else
                assert(prdata == {DATA_WIDTH{1'b0}});
        end
    end

    // Reset property.
    always @(posedge pclk) begin
        if (f_past_valid && !$past(presetn))
            assert(f_regs == {(4*DATA_WIDTH){1'b0}});
    end

    // Register update properties, per register and byte.
    genvar fr, fb;
    generate
        for (fr = 0; fr < 4; fr = fr + 1) begin : g_f_reg
            for (fb = 0; fb < STRB_WIDTH; fb = fb + 1) begin : g_f_byte
                always @(posedge pclk) begin
                    if (f_past_valid && $past(presetn)) begin
                        if ($past(f_access && pwrite && (paddr == 4*fr) && pstrb[fb]))
                            assert(f_regs[fr*DATA_WIDTH + 8*fb +: 8] == $past(pwdata[8*fb +: 8]));
                        else
                            assert(f_regs[fr*DATA_WIDTH + 8*fb +: 8] == $past(f_regs[fr*DATA_WIDTH + 8*fb +: 8]));
                    end
                end
            end
            always @(posedge pclk) begin
                if (f_past_valid && presetn)
                    cover(f_access && !pwrite && (paddr == 4*fr) && (prdata != 0));
            end
        end
    endgenerate

    // Covers.
    always @(posedge pclk) begin
        if (f_past_valid && presetn) begin
            cover(f_access && !pwrite && (paddr == 12) && (prdata == 32'h1234_5678));
            cover(f_access && pwrite && (paddr == 4) && (pstrb == 4'b0101));
            cover(f_access && pslverr);
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: apb_regs_tb.v ===
`timescale 1ns / 1ps
`default_nettype none

// Self-checking directed testbench for apb_regs.
// Inputs are driven just after the falling edge; outputs are sampled 1 ns
// later, well before the next rising edge.

module apb_regs_tb;

    reg         pclk;
    reg         presetn;
    reg  [7:0]  paddr;
    reg         psel;
    reg         penable;
    reg         pwrite;
    reg  [31:0] pwdata;
    reg  [3:0]  pstrb;
    wire [31:0] prdata;
    wire        pready;
    wire        pslverr;

    integer passed;
    integer failed;
    integer step;
    integer s;
    reg [31:0] model [0:3];
    reg [7:0]  a;
    reg [8*64-1:0] nonce;

    apb_regs #(
        .ADDR_WIDTH(8),
        .DATA_WIDTH(32)
    ) dut (
        .pclk    (pclk),
        .presetn (presetn),
        .paddr   (paddr),
        .psel    (psel),
        .penable (penable),
        .pwrite  (pwrite),
        .pwdata  (pwdata),
        .pstrb   (pstrb),
        .prdata  (prdata),
        .pready  (pready),
        .pslverr (pslverr)
    );

    initial pclk = 1'b0;
    always #5 pclk = ~pclk;

    // ---------------------------------------------------------------- model
    function tb_mapped(input [7:0] addr);
        begin
            tb_mapped = (addr[1:0] == 2'b00) && (addr < 8'h10);
        end
    endfunction

    function [31:0] tb_merge(input [31:0] old_val, input [31:0] data, input [3:0] strb);
        begin
            tb_merge[7:0]   = strb[0] ? data[7:0]   : old_val[7:0];
            tb_merge[15:8]  = strb[1] ? data[15:8]  : old_val[15:8];
            tb_merge[23:16] = strb[2] ? data[23:16] : old_val[23:16];
            tb_merge[31:24] = strb[3] ? data[31:24] : old_val[31:24];
        end
    endfunction

    // --------------------------------------------------------------- checks
    task check_data(input [31:0] got, input [31:0] exp);
        begin
            if (got === exp) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("step %0d paddr 0x%02h: prdata 0x%08h, expected 0x%08h",
                       step, paddr, got, exp);
            end
        end
    endtask

    task check_err(input got, input exp);
        begin
            if (got === exp) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("step %0d paddr 0x%02h: pslverr %0b, expected %0b",
                       step, paddr, got, exp);
            end
        end
    endtask

    task check_ready(input got);
        begin
            if (got === 1'b1) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("step %0d paddr 0x%02h: pready %0b in access phase, expected 1 (zero wait states)",
                       step, paddr, got);
            end
        end
    endtask

    task check_quiet;
        begin
            check_data(prdata, 32'h0000_0000);
            check_err(pslverr, 1'b0);
        end
    endtask

    // ------------------------------------------------------------ transfers
    task apb_write(input [7:0] addr, input [31:0] data, input [3:0] strb);
        reg exp_err;
        begin
            exp_err = !tb_mapped(addr);
            step = step + 1;
            @(negedge pclk);
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = 1'b1;
            paddr   = addr;
            pwdata  = data;
            pstrb   = strb;
            #1;
            check_quiet;
            @(negedge pclk);
            penable = 1'b1;
            #1;
            check_ready(pready);
            check_err(pslverr, exp_err);
            check_data(prdata, 32'h0000_0000);
            if (!exp_err)
                model[addr[3:2]] = tb_merge(model[addr[3:2]], data, strb);
        end
    endtask

    task apb_read(input [7:0] addr);
        reg        exp_err;
        reg [31:0] exp_data;
        begin
            exp_err  = !tb_mapped(addr);
            exp_data = exp_err ? 32'h0000_0000 : model[addr[3:2]];
            step = step + 1;
            @(negedge pclk);
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = 1'b0;
            paddr   = addr;
            pwdata  = 32'hDEAD_BEEF;
            pstrb   = 4'h0;
            #1;
            check_quiet;
            @(negedge pclk);
            penable = 1'b1;
            #1;
            check_ready(pready);
            check_err(pslverr, exp_err);
            check_data(prdata, exp_data);
        end
    endtask

    // Idle cycles with psel low. pen high models another completer's access
    // phase; pwrite and pstrb are active to show that no write happens.
    task apb_idle(input integer n, input pen);
        begin
            repeat (n) begin
                @(negedge pclk);
                psel    = 1'b0;
                penable = pen;
                pwrite  = 1'b1;
                paddr   = 8'h00;
                pwdata  = 32'hFFFF_FFFF;
                pstrb   = 4'hF;
                #1;
                check_quiet;
            end
        end
    endtask

    task apb_reset(input integer n);
        begin
            @(negedge pclk);
            presetn = 1'b0;
            psel    = 1'b0;
            penable = 1'b0;
            pwrite  = 1'b0;
            paddr   = 8'h00;
            pwdata  = 32'h0000_0000;
            pstrb   = 4'h0;
            repeat (n) begin
                #1;
                check_quiet;
                @(negedge pclk);
            end
            presetn  = 1'b1;
            model[0] = 32'h0000_0000;
            model[1] = 32'h0000_0000;
            model[2] = 32'h0000_0000;
            model[3] = 32'h0000_0000;
        end
    endtask

    task read_all;
        begin
            a = 8'h00;
            repeat (4) begin
                apb_read(a);
                a = a + 8'h04;
            end
        end
    endtask

    task unmapped(input [7:0] addr);
        begin
            apb_write(addr, 32'hFFFF_FFFF, 4'hF);
            apb_read(addr);
        end
    endtask

    // ------------------------------------------------------------- sequence
    initial begin
        passed   = 0;
        failed   = 0;
        step     = 0;
        presetn  = 1'b0;
        psel     = 1'b0;
        penable  = 1'b0;
        pwrite   = 1'b0;
        paddr    = 8'h00;
        pwdata   = 32'h0000_0000;
        pstrb    = 4'h0;
        a        = 8'h00;
        model[0] = 32'h0000_0000;
        model[1] = 32'h0000_0000;
        model[2] = 32'h0000_0000;
        model[3] = 32'h0000_0000;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce))
            nonce = {(8*64){1'b0}};

        // Reset values.
        apb_reset(3);
        apb_idle(2, 1'b0);
        read_all;

        // Write then read every register; back-to-back writes, idle gap, reads.
        apb_write(8'h00, 32'h0123_4567, 4'hF);
        apb_write(8'h04, 32'h89AB_CDEF, 4'hF);
        apb_write(8'h08, 32'hDEAD_BEEF, 4'hF);
        apb_write(8'h0C, 32'hCAFE_F00D, 4'hF);
        apb_idle(1, 1'b0);
        read_all;

        // Back-to-back write/read alternation.
        apb_write(8'h04, 32'h5555_AAAA, 4'hF);
        apb_read(8'h04);
        apb_write(8'h00, 32'hFFFF_FFFF, 4'hF);
        apb_read(8'h00);
        apb_read(8'h0C);

        // Every strobe pattern (including none) on REG2.
        for (s = 0; s < 16; s = s + 1) begin
            apb_write(8'h08, {8{s[3:0]}} ^ 32'hA5C3_5A3C, s[3:0]);
            apb_read(8'h08);
        end

        // Single-lane partial writes on REG1 with idle gaps.
        apb_write(8'h04, 32'h0000_0011, 4'b0001);
        apb_idle(2, 1'b0);
        apb_read(8'h04);
        apb_write(8'h04, 32'h0000_2200, 4'b0010);
        apb_idle(1, 1'b0);
        apb_read(8'h04);
        apb_write(8'h04, 32'h0033_0000, 4'b0100);
        apb_read(8'h04);
        apb_write(8'h04, 32'h4400_0000, 4'b1000);
        apb_read(8'h04);
        apb_write(8'h0C, 32'h1234_5678, 4'h0);
        apb_read(8'h0C);

        // psel low with penable and pwrite active: no write, quiet outputs.
        apb_idle(1, 1'b0);
        apb_idle(1, 1'b1);
        apb_idle(1, 1'b0);
        apb_idle(1, 1'b1);
        read_all;

        // PSLVERR policy: misaligned and out-of-range addresses.
        unmapped(8'h01);
        unmapped(8'h02);
        unmapped(8'h03);
        unmapped(8'h05);
        unmapped(8'h06);
        unmapped(8'h07);
        unmapped(8'h0D);
        unmapped(8'h0E);
        unmapped(8'h0F);
        unmapped(8'h10);
        unmapped(8'h14);
        unmapped(8'h18);
        unmapped(8'h1C);
        unmapped(8'h20);
        unmapped(8'h40);
        unmapped(8'h80);
        unmapped(8'hFC);
        unmapped(8'hFF);
        read_all;

        // Mapped and unmapped transfers back to back.
        apb_read(8'h10);
        apb_read(8'h00);
        apb_write(8'h13, 32'h0BAD_0BAD, 4'hF);
        apb_read(8'h0C);
        apb_write(8'h0C, 32'h600D_600D, 4'hF);
        apb_read(8'h1C);
        apb_read(8'h0C);

        // Reset again.
        apb_reset(2);
        read_all;
        apb_write(8'h0C, 32'h1357_9BDF, 4'hF);
        apb_read(8'h0C);
        apb_idle(2, 1'b0);

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    // Watchdog: only fires if the sequence hangs.
    initial begin
        #1000000;
        failed = failed + 1;
        $error("watchdog: simulation did not complete");
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`default_nettype wire
=== END FILE ===
